uniform vec2 iResolution;
uniform float iTime;
uniform shader composable;
uniform float uSpeed;              // min: 0.1, max: 5.0, default: 0.4, 회전 속도
uniform float uRectWidth;          // min: 0.1, max: 2.0, default: 0.7, 사각형 가로 크기
uniform float uRectHeight;         // min: 0.1, max: 2.0, default: 0.7, 사각형 세로 크기
uniform float uSquirclePower;      // min: 2.0, max: 8.0, default: 5.2, Squircle 곡률 (높을수록 각짐)
uniform float uMarginHorizontal;   // min: 0.0, max: 0.5, default: 0.0, 좌우 마진
uniform float uMarginVertical;     // min: 0.0, max: 0.5, default: 0.0, 상하 마진
uniform float uThickness;          // min: 0.01, max: 0.2, default: 0.1, 기본 두께(중앙 기준)
uniform float uTailLength;         // min: 0.1, max: 1.0, default: 0.6, 꼬리 길이 (0~1)
uniform vec3 uColor1;             // min: [0.0, max: [1.0, default: [1.0, 0.6, 0.5], 그라데이션 1
uniform vec3 uColor2;             // min: [0.0, max: [1.0, default: [0.9, 0.4, 0.4], 그라데이션 2
uniform vec3 uColor3;             // min: [0.0, max: [1.0, default: [0.8, 0.7, 1.0], 그라데이션 3
uniform vec3 uColor4;             // min: [0.0, max: [1.0, default: [0.5, 0.7, 1.0], 그라데이션 4
uniform float uAlpha;              // min: 0.0, max: 1.0, default: 1.0, 전체 투명도
uniform float uHeadThin;      // min: 0.2, max: 1.0, default: 0.7, 헤드 최소 두께 비율
uniform float uTailThin;      // min: 0.0, max: 0.8, default: 0.3, 꼬리 끝 최소 두께 비율
uniform float uFeather;       // min: 0.2, max: 1.5, default: 0.8, 가장자리 부드러움
uniform float uTailFadePow;   // min: 0.5, max: 4.0, default: 3.4, 꼬리 밝기 감소 곡률
uniform vec3 u2Color1;       // min: [0.0, max: [1.0, default: [0.9, 1.0, 0.5], 2번 그라데이션 1 (쿨 톤 권장)
uniform vec3 u2Color2;       // min: [0.0, max: [1.0, default: [0.7, 1.0, 0.6], 2번 그라데이션 2
uniform vec3 u2Color3;       // min: [0.0, max: [1.0, default: [0.7, 1.0, 0.5], 2번 그라데이션 3
uniform vec3 u2Color4;       // min: [0.0, max: [1.0, default: [0.5, 0.9, 0.9], 2번 그라데이션 4(하이라이트)
uniform float u2Alpha;        // min: 0.0, max: 1.0, default: 0.9, 두 번째 꼬리 알파(강도)
vec2 getSquirclePoint(float t, vec2 size, float n) {
    t = mod(t, 1.0);
    float angle = t * 6.28318530718; // 2*PI

    float halfW = size.x * 0.5;
    float halfH = size.y * 0.5;

    float cosA = cos(angle);
    float sinA = sin(angle);

    float absCosA = abs(cosA);
    float absSinA = abs(sinA);

    absCosA = max(absCosA, 0.0001);
    absSinA = max(absSinA, 0.0001);

    float powCos = pow(absCosA, n);
    float powSin = pow(absSinA, n);

    float denom = pow(powCos + powSin, 1.0 / n);
    denom = max(denom, 0.0001);

    float x = halfW * sign(cosA) * absCosA / denom;
    float y = halfH * sign(sinA) * absSinA / denom;

    return vec2(x, y);
}

float taperedThickness(float p) {
    float head = mix(uHeadThin, 1.0, smoothstep(0.0, 0.35, p));
    float tail = mix(1.0, uTailThin, smoothstep(0.55, 1.0, p));
    float bell = 1.0 - abs(p - 0.5) * 1.6; bell = clamp(bell, 0.0, 1.0);
    float profile = head * tail * bell;
    return uThickness * clamp(profile, 0.0, 1.0);
}

float tailBrightness(float p) { return pow(1.0 - p, uTailFadePow); }

vec3 rampColor(float phase, vec3 c1, vec3 c2, vec3 c3, vec3 c4) {
    float t = mod(phase, 1.0) * 4.0;
    if (t < 1.0) return mix(c1, c2, t);
    if (t < 2.0) return mix(c2, c3, t - 1.0);
    if (t < 3.0) return mix(c3, c4, t - 2.0);
    return mix(c4, c1, t - 3.0);
}

vec4 main(vec2 fragCoord)
{

    // Y 방향 반전
    vec2 uv = fragCoord / iResolution.xy;

    // 마진 적용하여 유효 영역 계산
    vec2 marginMin = vec2(uMarginHorizontal, uMarginVertical);
    vec2 marginMax = vec2(1.0 - uMarginHorizontal, 1.0 - uMarginVertical);
    vec2 validSize = marginMax - marginMin;

    // 중심점을 유효 영역 중심으로 설정
    vec2 center = (marginMin + marginMax) * 0.5;

    // 화면 비율 고려
    float aspect = iResolution.x / iResolution.y;
    vec2 adjustedSize = vec2(uRectWidth, uRectHeight);

    // 유효 영역에 맞게 사각형 크기 조정
    adjustedSize.x *= validSize.x;
    adjustedSize.y *= validSize.y;

    // 비율 보정
    if (aspect > 1.0) {
        adjustedSize.x *= aspect;
    } else {
        adjustedSize.y /= aspect;
    }

    vec2 pos = uv - center;

    // 화면 비율에 따라 좌표 조정
    if (aspect > 1.0) {
        pos.x *= aspect;
    } else {
        pos.y /= aspect;
    }

    float baseTime = iTime * uSpeed;

    vec3  accColor = vec3(0.0);
    float accAlpha = 0.0;

    int samples = 64;

    // --- Tail #1 (기존) ---
    for (int i = 0; i < 64; i++) {
        if (i >= samples) break;
        float t = float(i) / float(samples - 1) * uTailLength;
        float p = t / uTailLength;
        vec2 pathPos = getSquirclePoint(baseTime - t, adjustedSize, uSquirclePower);
        float thick = taperedThickness(p);
        float d = distance(pos, pathPos);
        if (d < thick * (1.0 + uFeather)) {
            vec3 col = rampColor(baseTime - t + 0.25, uColor1, uColor2, uColor3, uColor4);
            float edge = 1.0 - smoothstep(thick * (1.0 - 0.35 * uFeather),
                                          thick * (1.0 + 0.65 * uFeather), d);
            float a = edge * tailBrightness(p) * uAlpha;
            accColor += col * a;
            accAlpha = max(accAlpha, a);
        }
    }

    // --- Tail #2 (정확히 반대편: +0.5 위상 오프셋) ---
    float oppositeTime = baseTime + 0.5;
    for (int i = 0; i < 64; i++) {
        if (i >= samples) break;
        float t = float(i) / float(samples - 1) * uTailLength;
        float p = t / uTailLength;
        vec2 pathPos = getSquirclePoint(oppositeTime - t, adjustedSize, uSquirclePower);
        float thick = taperedThickness(p);
        float d = distance(pos, pathPos);
        if (d < thick * (1.0 + uFeather)) {
            vec3 col = rampColor(oppositeTime - t + 0.25, u2Color1, u2Color2, u2Color3, u2Color4);
            float edge = 1.0 - smoothstep(thick * (1.0 - 0.35 * uFeather),
                                          thick * (1.0 + 0.65 * uFeather), d);
            float a = edge * tailBrightness(p) * u2Alpha;
            accColor += col * a;
            accAlpha = max(accAlpha, a);
        }
    }

    accColor = clamp(accColor, 0.0, 1.0);
return vec4(accColor, clamp(accAlpha, 0.0, 1.0));

}

