uniform float u2Alpha;        // min: 0.0, max: 1.0, default: 0.9, 두 번째 꼬리 알파(강도)

// ====== 경로 함수: Squircle (시계 방향, 바깥쪽 곡선) ======
vec2 getSquirclePoint(float t, vec2 size, float n) {
    t = mod(t, 1.0);
    float angle = t * 6.28318530718; // 2*PI

    float halfW = size.x * 0.5;
    float halfH = size.y * 0.5;

    float cosA = cos(angle);
    float sinA = sin(angle);

    float absCosA = abs(cosA);
    float absSinA = abs(sinA);

    absCosA = max(absCosA, 0.0001);
    absSinA = max(absSinA, 0.0001);

    float powCos = pow(absCosA, n);
    float powSin = pow(absSinA, n);

    float denom = pow(powCos + powSin, 1.0 / n);
    denom = max(denom, 0.0001);

    float x = halfW * sign(cosA) * absCosA / denom;
    float y = halfH * sign(sinA) * absSinA / denom;

    return vec2(x, y);
}

// 두께 프로파일(0=헤드, 1=꼬리끝)
float taperedThickness(float p) {
    float head = mix(uHeadThin, 1.0, smoothstep(0.0, 0.35, p));
    float tail = mix(1.0, uTailThin, smoothstep(0.55, 1.0, p));
    float bell = 1.0 - abs(p - 0.5) * 1.6; bell = clamp(bell, 0.0, 1.0);
    float profile = head * tail * bell;
    return uThickness * clamp(profile, 0.0, 1.0);
}

// 길이 방향 밝기
float tailBrightness(float p) { return pow(1.0 - p, uTailFadePow); }

// 4색 그라데이션
vec3 rampColor(float phase, vec3 c1, vec3 c2, vec3 c3, vec3 c4) {
    float t = mod(phase, 1.0) * 4.0;
    if (t < 1.0) return mix(c1, c2, t);
    if (t < 2.0) return mix(c2, c3, t - 1.0);
    if (t < 3.0) return mix(c3, c4, t - 2.0);
    return mix(c4, c1, t - 3.0);
