    }

    // --- Tail #2 (정확히 반대편: +0.5 위상 오프셋) ---
    float oppositeTime = baseTime + 0.5;
    for (int i = 0; i < 64; i++) {
        if (i >= samples) break;
        float t = float(i) / float(samples - 1) * uTailLength;
