        vec2 pathPos = getSquirclePoint(oppositeTime - t, adjustedSize, uSquirclePower);
        float thick = taperedThickness(p);
        float d = distance(pos, pathPos);
        if (d < thick * (1.0 + uFeather)) {
            vec3 col = rampColor(oppositeTime - t + 0.25, u2Color1, u2Color2, u2Color3, u2Color4);
            float edge = 1.0 - smoothstep(thick * (1.0 - 0.35 * uFeather),
